// School locations refer to the source school, never the student's address.
// Keep raw records/IDs intact; these city-scoped aliases are for the directory only.
const SchoolAreas = (() => {
  const unknown = '区域未细分';
  const aliases = {
    '东莞市': {'松山湖园区':'松山湖', '松山湖管委会':'松山湖', '松山湖高新区':'松山湖'},
    '惠州市': {'大亚湾区':'大亚湾开发区', '大亚湾经济技术开发区':'大亚湾开发区'}
  };
  const collator = new Intl.Collator('zh-CN');
  const norm = s => String(s ?? '').normalize('NFKC').replace(/[\s·]/g,'');
  const shortCity = city => city.replace(/市$/,'');
  function parts(city, raw) {
    const values = norm(raw).split(/[/、,;]+/).filter(Boolean).map(v => {
      if ([city, shortCity(city)+'市区', '市区', '市辖区', '其他', '其它', '未填写', '0'].includes(v)) return unknown;
      const table=aliases[city];
      return table && Object.hasOwn(table,v) ? table[v] : v;
    });
    return [...new Set(values.length ? values : [unknown])];
  }
  function directory(raw) {
    return Object.fromEntries(Object.entries(raw).map(([city,fields]) => {
      const items = new Set(fields.flatMap(x => parts(city,x)));
      return [city,[...items].sort((a,b)=>(a===unknown)-(b===unknown)||collator.compare(a,b))];
    }));
  }
  function match(dir, query) {
    const q = norm(query);
    if(q.length<2) return [];
    const hits=[];
    for(const [city,regions] of Object.entries(dir)) {
      const key=[city,shortCity(city)].find(k=>q.startsWith(k));
      const needle=key?q.slice(key.length):q;
      for(const area of regions) {
        if(area===unknown) continue;
        const names=[area,...Object.entries(aliases[city]||{}).filter(([,to])=>to===area).map(([from])=>from)];
        if((key&&!needle)||names.some(n=>n.includes(needle))) hits.push({city,area,exact:names.includes(needle)});
      }
    }
    return hits.sort((a,b)=>Number(b.exact)-Number(a.exact)||collator.compare(a.city,b.city)||collator.compare(a.area,b.area));
  }
  function scope(schools, city, area) {
    const local=[], cross=[];
    for(const school of schools) {
      if(!area) {local.push(school);continue;}
      const loc=parts(city,school.district);
      if(loc.includes(area)) (loc.length===1?local:cross).push(school);
    }
    return {local,cross};
  }
  function rows(schools, year) {
    return schools.map(s=>({...s,period_total:year==null?s.period_total:(s.years[year]??0)}))
      .filter(s=>s.period_total>0)
      .sort((a,b)=>b.period_total-a.period_total||collator.compare(a.name,b.name)||a.id.localeCompare(b.id));
  }
  function annual(schools, coverage) {
    return coverage.map(y=>({...y,count:y.count===null?null:schools.reduce((n,s)=>n+(s.years[y.year]??0),0)}));
  }
  return {unknown,parts,directory,match,scope,rows,annual};
})();

